    len += messages_ary_len;
    if (len > 0x7fffffff) {
        return NULL; // a frame length is an i32, and so is every buffer size argument
    }
    msg = (ams::MsgBlock*)alloc.begin(alloc.ctx, int(len));
    if (!msg) {
        return NULL; // no room.
    }
    msg->type = u32(1);
    msg->length = u32(len);
    msg->first_seqno = first_seqno;
    msg->n_messages = n_messages;
